#!/usr/bin/env bash
# Question 5: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q5_FAULT}" in
  kubelet-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q5_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q5_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  containerd-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q5_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q5_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-binary-path)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q5_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q5_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
esac
